  create policy "Users can view their own profile"
  on "public"."profiles"
  as permissive
  for select
  to authenticated
using ((( SELECT auth.uid() AS uid) = id));



  create policy "Users can view their own student details"
  on "public"."student_details"
  as permissive
  for select
  to public
using ((( SELECT auth.uid() AS uid) = id));



  create policy "Users can view their own teacher details"
  on "public"."teacher_details"
  as permissive
  for select
  to public
using ((( SELECT auth.uid() AS uid) = id));




